rollback.sql:
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM review_batch WHERE status = 'BUDGET_EXHAUSTED') THEN
        RAISE EXCEPTION 'Cannot remove a status used by existing scheduled runs. Restore a verified backup before downgrading.';
    END IF;
END $$;
ALTER TABLE review_batch DROP CONSTRAINT ck_review_batch_status;
ALTER TABLE review_batch ADD CONSTRAINT ck_review_batch_status CHECK (status IN ('AWAITING_CONFIRMATION', 'RUNNING', 'PAUSED', 'COMPLETED', 'CANCELLED'));
